#[derive(Debug)]
enum DateTime64 {
    Nat,
    Valid(u64),
}

/// Returns a vector of booleans indicating whether each DateTime64 in the input vector is Nat.
///
/// # Parameters
/// - `x`: A vector of DateTime64 values.
///
/// # Returns
/// A vector of booleans where each element corresponds to whether the respective DateTime64
/// in the input vector is Nat.
///
/// # Requires
/// - The input vector `x` must not be empty.
///
/// # Ensures
/// - The length of the output vector is equal to the length of the input vector.
/// - For each index `i`, if `x[i]` is `DateTime64::Nat`, then the output at index `i` is `true`.
/// - For each index `i`, if `x[i]` is `DateTime64::Valid(_)`, then the output at index `i` is `false`.
fn isnat(x: Vec<DateTime64>) -> Vec<bool> {
    // Ensure that the input vector is not empty
    assert!(!x.is_empty());

    // Create a vector to hold the results
    let mut result = Vec::with_capacity(x.len());

    // Iterate over the input vector and map each DateTime64 to a boolean
    for date_time in &x {
        match date_time {
            DateTime64::Nat => result.push(true),
            DateTime64::Valid(_) => result.push(false),
        }
    }

    // Ensure the output vector has the same length as the input vector
    assert_eq!(result.len(), x.len());

    result
}

fn main() {
    // Example usage
    let input = vec![
        DateTime64::Nat,
        DateTime64::Valid(1622547800),
        DateTime64::Nat,
        DateTime64::Valid(1622547900),
    ];
    
    let result = isnat(input);
    println!("{:?}", result); // Output: [true, false, true, false]
}